import {makeSequence,checkSequence} from '../logic.js';import {gameFrame,roundFlow} from '../ui.js';
export function mountGame(root,c){const flow=roundFlow(root,c);let length=c.difficulty==='easy'?3:c.difficulty==='hard'?5:4,best=0;function next(){flow.next();const seq=makeSequence(length,c.difficulty==='hard'?'123456789ABCDEFG':'123456789');const area=gameFrame(root,'Watch the sequence',`${length} characters. Keep them in order.`);area.innerHTML='<div class="sequence-display" aria-live="off">Ready</div><p class="subtle">The answer field appears after the sequence.</p>';const speed=c.difficulty==='easy'?1000:c.difficulty==='hard'?550:750;seq.forEach((value,i)=>{c.session.schedule(()=>area.querySelector('.sequence-display').textContent=value,600+i*(speed+200));c.session.schedule(()=>area.querySelector('.sequence-display').textContent='',600+i*(speed+200)+speed);});c.session.schedule(()=>{area.innerHTML=`<form id="recall"><label class="input-label" for="sequence">Enter the sequence in order</label><input id="sequence" class="recall-input" inputmode="${c.difficulty==='hard'?'text':'numeric'}" autocomplete="off" maxlength="20" placeholder="Your sequence" aria-describedby="recall-tip"><p id="recall-tip" class="subtle">Spaces are ignored. Letters are not case-sensitive.</p><button class="primary">Check sequence</button></form>`;const input=area.querySelector('input');input.focus();area.querySelector('form').onsubmit=e=>{e.preventDefault();const actual=input.value.toUpperCase().replace(/\s/g,'').split(''),correct=checkSequence(seq,actual);if(correct){best=Math.max(best,length);length=Math.min(12,length+1);}else length=Math.max(3,length-1);flow.answer(correct,`The sequence was ${seq.join(' ')}.`,next,{span:best});};},600+seq.length*(speed+200));}next();return {dispose(){}};}
